@router.post("/users/{user_id}/role")
def set_role(request: Request, user_id: str) -> Response:
    payload = request.json()
    role = payload["role"]
    notify = payload.get("notify", True)
    db.execute("UPDATE users SET role = ? WHERE id = ?", (role, int(user_id)))
    if not notify:
        return Response(status=204)
    user = get_user(db, int(user_id))
    send_email(user.email, "Your role has changed", f"You are now {role}.")
    return Response(status=204)

@router.post("/users/{user_id}/deactivate")
def deactivate_user(request: Request, user_id: str) -> Response:
    changed = db.execute("UPDATE users SET active = 0 WHERE id = ?", (int(user_id),))
    if changed == 0:
        raise HTTPError(404, "user not found")

def get_user(db: Database, user_id: int) -> User | None:
    """Return the user, or None if no such user exists."""
    row = db.query_one("SELECT id, email, role, active FROM users WHERE id = ?", (user_id,))
    if row is None:
        return None
